// Convierte el webhook de la app Ruta en un mensaje de WhatsApp y prepara el cuerpo
// para verificar la firma (HMAC) en el nodo siguiente.
const req = $('Webhook').first().json;
const headers = req.headers || {};
const body = req.body || {};
const d = body.datos || {};
const evento = headers['x-ruta-evento'] || body.evento || 'desconocido';
const emp = (body.empresa && body.empresa.nombre) || '';
const titulo = body.descripcion || evento;

const L = (k, v) => (v === undefined || v === null || v === '') ? '' : `\n*${k}:* ${v}`;
const peticion = [d.metodo, d.url].filter(Boolean).join(' ');

let cuerpo = '';
let icono = '🔔';

if (evento === 'sistema.error') {
  // Error inesperado de la plataforma.
  icono = '🔴';
  cuerpo = L('Referencia', d.referencia) + L('Tipo', d.clase) + L('Mensaje', d.mensaje)
    + L('Dónde', d.donde) + L('Petición', peticion)
    + L('Veces', d.ocurrencias) + L('Panel', d.panel);
} else if (evento === 'sistema.salud') {
  // Un servicio de la app o de un proveedor está fallando.
  icono = '🟠';
  cuerpo = L('Chequeo', d.chequeo) + L('Panel', d.panel);
} else if (evento === 'preoperacional.no_apto') {
  icono = '⛔';
  const fallas = (d.fallas || []).map(f => `• ${f.descripcion}${f.critico ? ' (crítica)' : ''}`).join('\n');
  cuerpo = L('Vehículo', d.placa) + L('Conductor', d.conductor)
    + (fallas ? `\n*Fallas:*\n${fallas}` : '') + L('Verificación', d.verificacion);
} else if (evento === 'servicio.novedad') {
  icono = '⚠️';
  const mapa = (d.latitud && d.longitud) ? `https://maps.google.com/?q=${d.latitud},${d.longitud}` : '';
  cuerpo = L('Vehículo', d.placa) + L('Ruta', d.ruta) + L('Conductor', d.conductor)
    + L('Novedad', d.novedad) + L('Ubicación', mapa);
} else if (evento === 'transito.comparendo_nuevo' || evento === 'transito.licencia_suspendida') {
  icono = '🚨';
  cuerpo = L(d.sujeto === 'conductor' ? 'Conductor' : 'Vehículo', d.nombre)
    + L('Placa', d.placa) + L('Documento', d.documento) + L('Detalle', d.detalle);
} else if (evento.startsWith('plan_accion.')) {
  icono = '📋';
  cuerpo = L('Plan', d.plan) + L('Vehículo', d.placa) + L('Título', d.titulo)
    + L('Prioridad', d.prioridad) + L('Responsable', d.responsable) + L('Fecha límite', d.fecha_limite);
} else if (evento.startsWith('mantenimiento.')) {
  icono = '🔧';
  cuerpo = L('Vehículo', d.placa) + L('Actividad', d.actividad || d.titulo)
    + L('Fecha', d.fecha || d.fecha_limite || d.fecha_programada);
} else {
  // Cualquier otro evento: se vuelcan los datos simples.
  cuerpo = Object.keys(d)
    .filter(k => ['string', 'number', 'boolean'].includes(typeof d[k]))
    .map(k => `*${k}:* ${d[k]}`)
    .join('\n');
}

const text = (`${icono} *${titulo}*` + (emp ? `\n_${emp}_` : '') + '\n' + cuerpo).trim();

// Cuerpo tal cual lo firma la app (JSON compacto), para recalcular el HMAC.
const cuerpoJson = JSON.stringify(body);

return [{ json: {
  evento,
  text,
  number: $('Configuración').first().json.DESTINO,
  cuerpoJson,
  firmaRecibida: headers['x-ruta-firma'] || ''
} }];
